import sys
H, W, N = map(int, sys.stdin.readline().split())
grid = [["."] * W for _ in range(H)]
directions = [(0, -1), (1, 0), (0, 1), (-1, 0)]
dirNum = 0
x, y = 1, 1

for _ in range(N):
    if grid[y-1][x-1] == ".":
        grid[y-1][x-1] = "#"
        dirNum += 1
    else:
        grid[y-1][x-1] = "."
        dirNum -= 1

    y += directions[dirNum % 4][1]
    x += directions[dirNum % 4][0]

    if x > W:
        x = 1
    elif x < 1:
        x = W
    if y > H:
        y = 1
    elif y < 1:
        y = H

for row in grid:
    print("".join(row))
